const origin = 'https://mobilizafacilities.com.br';
const routes = [
  { key: 'home', path: '/' },
  { key: 'login', path: '/entrar' },
  { key: 'maintenance', path: '/formularios/manutencao' },
  { key: 'purchase', path: '/formularios/compra' },
];
return routes.map(route => ({ json: { ...route, url: origin + route.path } }));

const routes = $('Rotas públicas').all();
const responses = new Map();
for (const [index, item] of $input.all().entries()) {
  const paired = Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem;
  const position = Number.isSafeInteger(paired?.item) ? paired.item : index;
  if (!responses.has(position)) responses.set(position, item.json);
}

const hasLink = (html, path) => {
  const links = [...html.matchAll(/\bhref\s*=\s*["']([^"']+)["']/gi)];
  return links.some(link => link[1].split('?')[0] === path);
};
const hasInput = (html, type) => new RegExp('<input\\b[^>]*\\btype\\s*=\\s*["\']' + type + '["\']', 'i').test(html);
const looksRight = (html, key) => {
  if (key === 'home') return hasLink(html, '/entrar') && hasLink(html, '/formularios/manutencao') && hasLink(html, '/formularios/compra');
  if (key === 'login') return hasInput(html, 'email') && hasInput(html, 'password');
  if (key === 'maintenance') return /solicitação de manutenção|canal de manutenção/i.test(html);
  if (key === 'purchase') return /pedido de compra/i.test(html);
  return false;
};

const checks = routes.map(({ json: route }, index) => {
  const response = responses.get(index);
  const status_code = Number.isSafeInteger(response?.statusCode) ? response.statusCode : null;
  const body = typeof response?.body === 'string' ? response.body : typeof response?.data === 'string' ? response.data : '';
  const result = status_code === null ? 'transport_error' : status_code !== 200 ? 'http_error' : looksRight(body, route.key) ? 'ok' : 'content_mismatch';
  return { path: route.path, status_code, result };
});
if (checks.length !== 4 || checks.some(check => check.result !== 'ok')) {
  const summary = checks.map(check => check.path + ' ' + (check.status_code ?? 'sem resposta') + ' ' + check.result).join(' | ');
  throw new Error('Saúde pública indisponível — ' + summary);
}
return [{ json: { healthy: true, checks } }];
